 /// &#x3C;/summary> [ObservableProperty] private string _deviceState = \\\"RUN\\\"; /// &#x3C;summary> /// 等效电阻 /// &#x3C;/summary> [ObservableProperty] private string _equivalentResistance = \\\"9999+\\\"; /// &#x3C;summary> /// 输出电流百分比 /// &#x3C;/summary> [ObservableProperty] private float _outputCurrentPercentage; /// &#x3C;summary> /// 输出功率百分比 /// &#x3C;/summary> [ObservableProperty] private float _outputPowerPercentage; /// &#x3C;summary> /// 输出电压百分比 /// &#x3C;/summary> [ObservableProperty] private float _outputVoltagePercentage; /// &#x3C;summary> /// 输出电压显示文本 /// &#x3C;/summary> [ObservableProperty] private string _outputVoltageString = \\\"00.00\\\"; private float _outputVoltage; /// &#x3C;summary> /// 输出电压 /// &#x3C;/summary> public float OutputVoltage { get => _outputVoltage; set { if (SetProperty(ref _outputVoltage, value)) { OutputVoltageString = $\\\"{value:00.00}\\\"; OutputVoltagePercentage = OutputVoltage / SettingOvp * 100f; SetEquivalentResistance(); } } } /// &#x3C;summary> /// 设置的输出电压 /// &#x3C;/summary> [ObservableProperty] private float _outputVoltageSetting; private float _outputVoltageSettingFromDevice; /// &#x3C;summary> /// 从设备获取的设置电压 /// &#x3C;/summary> public float OutputVoltageSettingFromDevice { get => _outputVoltageSettingFromDevice; set { if (SetProperty(ref _outputVoltageSettingFromDevice, value)) OutputVoltageSetting = value; } } /// &#x3C;summary> /// 输出电流 /// &#x3C;/summary> [ObservableProperty] private string _outputCurrentString = \\\"0.000\\\"; private float _outputCurrent; /// &#x3C;summary> /// 输出电流 /// &#x3C;/summary> public float OutputCurrent { get => _outputCurrent; set { if (SetProperty(ref _outputCurrent, value)) { OutputCurrentString = TotalLimitNum2String(value, 5); OutputCurrentPercentage = OutputCurrent / SettingOcp * 100f; SetEquivalentResistance(); } } } /// &#x3C;summary> /// 设置的输出电流 /// &#x3C;/summary> [ObservableProperty] private float _outputCurrentSetting; private float _outputCurrentSettingFromDevice; /// &#x3C;summary> /// 从设备获取的设置电流 /// &#x3C;/summary> public float OutputCurrentSettingFromDevice { get => _outputCurrentSettingFromDevice; set { if (SetProperty(ref _outputCurrentSettingFromDevice, value)) OutputCurrentSetting = value; } } /// &#x3C;summary> /// 输出功率 /// &#x3C;/summary> [ObservableProperty] private string _outputPowerString = \\\"0.000\\\"; private float _outputPower; /// &#x3C;summary> /// 输出功率 /// &#x3C;/summary> public float OutputPower { get => _outputPower; set { if (SetProperty(ref _outputPower, value)) { OutputPowerString = TotalLimitNum2String(value, 5); OutputPowerPercentage = OutputPower / SettingOpp * 100f; } } } /// &#x3C;summary> /// 输入电压 /// &#x3C;/summary> [ObservableProperty] private string _inputVoltage = \\\"24.0V\\\"; /// &#x3C;summary> /// 内部温度 /// &#x3C;/summary> [ObservableProperty] private string _internalTemperature = \\\"10.0℃\\\"; /// &#x3C;summary> /// 累计电流 /// &#x3C;/summary> [ObservableProperty] private string _totalCurrentCount = \\\"0000.000AH\\\"; /// &#x3C;summary> /// 累计功率 /// &#x3C;/summary> [ObservableProperty] private string _totalPowerCount = \\\"0000.000WH\\\"; /// &#x3C;summary> /// 过压保护显示文本 /// &#x3C;/summary> [ObservableProperty] private string _settingOvpString = \\\"50.00\\\"; private float _settingOvp; /// &#x3C;summary> /// 过压保护 /// &#x3C;/summary> public float SettingOvp { get => _settingOvp; set { if (SetProperty(ref _settingOvp, value)) { SettingOvpString = TotalLimitNum2String(value, 5); OutputVoltagePercentage = OutputVoltage / SettingOvp * 100f; } } } /// &#x3C;summary> /// 过流保护显示文本 /// &#x3C;/summary> [ObservableProperty] private string _settingOcpString = \\\"11.00\\\"; private float _settingOcp; /// &#x3C;summary> /// 过流保护 /// &#x3C;/summary> public float SettingOcp { get => _settingOcp; set { if (SetProperty(ref _settingOcp, value)) { SettingOcpString = TotalLimitNum2String(value, 5); OutputCurrentPercentage = OutputCurrent / SettingOcp * 100f; } } } /// &#x3C;summary> /// 过功率保护 /// &#x3C;/summary>